v_Kp = sel
  case Am_Kp == 0 {J_per_mol}: kappa_Kp * (exp((mu_Ki + mu_O_Kp + zK * F * V_mem) / (R * T)) - exp((mu_Ke + mu_O_Kp) / (R * T)));
  otherwise: kappa_Kp * Am_Kp / (R * T) / (exp(Am_Kp / (R * T)) - 1) * (exp((mu_Ki + mu_O_Kp + zK * F * V_mem) / (R * T)) - exp((mu_Ke + mu_O_Kp) / (R * T)));
endsel;

v_K1 = sel
  case Am_K1 == 0 {J_per_mol}: kappa_K1 * (exp((mu_Ki + mu_O_K1 + nK * mu_Ke + zK * F * V_mem) / (R * T)) - exp((mu_Ke + mu_O_K1 + nK * mu_Ke) / (R * T)));
  otherwise: kappa_K1 * Am_K1 / (R * T) / (exp(Am_K1 / (R * T)) - 1) * (exp((mu_Ki + mu_O_K1 + nK * mu_Ke + zK * F * V_mem) / (R * T)) - exp((mu_Ke + mu_O_K1 + nK * mu_Ke) / (R * T)));
endsel;

